import concurrent.futures, urllib.request
covers = [('midnight-library','9780525559474'),('tomorrow','9780593321201'),('psychology-of-money','9780857197689'),('atomic-habits','9780735211292'),('alchemist','9780061122415'),('little-life','9780804172707')]
def download(item):
    name, isbn = item
    try:
        urllib.request.urlretrieve('https://covers.openlibrary.org/b/isbn/'+isbn+'-L.jpg', 'public/covers/'+name+'.jpg')
        return name+' downloaded'
    except Exception as e:
        return name+': '+str(e)
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
    print('\\n'.join(pool.map(download, covers)))
