args.command:
/bin/bash -lc "mkdir -p /tmp/chapter-checks && node --input-type=module <<'JS'
import { chromium } from '@playwright/test';
const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1100},deviceScaleFactor:1});
page.on('pageerror',error=>console.log('PAGE ERROR:',error.message));
await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
await page.screenshot({path:'/tmp/chapter-checks/desktop.png',fullPage:true});
console.log(await page.locator('.welcome, .library-toolbar, .reading-grid, .finished-grid').evaluateAll(elements=>elements.map(el=>({class:el.className,rect:el.getBoundingClientRect().toJSON()}))));
console.log('covers',await page.locator('img').evaluateAll(images=>images.map(img=>({src:img.src,loaded:img.complete&&img.naturalWidth>0,width:img.naturalWidth}))));
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/chapter-checks/mobile.png',fullPage:true});
console.log('mobile width:',await page.evaluate(()=>({viewport:window.innerWidth,document:document.documentElement.scrollWidth})));
await browser.close();
JS"

