/bin/bash -lc "node --input-type=module <<'JS'
import { chromium, expect } from '@playwright/test';
const browser = await chromium.launch({headless:true,args:['--no-sandbox','--disable-gpu']});
const context = await browser.newContext({viewport:{width:1440,height:1000},permissions:['clipboard-read','clipboard-write']});
const page = await context.newPage();
const errors=[];
page.on('pageerror',error=>errors.push(error.message));
let bookId;
try {
  await page.goto('http://localhost:3000', {waitUntil:'networkidle'});
  await expect(page.locator('.reading-card')).toHaveCount(3);
  await expect(page.locator('.finished-card')).toHaveCount(4);
  await page.getByRole('button',{name:'Add a book',exact:true}).click();
  await expect(page.getByRole('dialog')).toBeVisible();
  await page.getByLabel('Book title').fill('A Book of Days — Browser Check');
  await page.getByLabel('Author',{exact:true}).fill('Patti Smith');
  await page.getByLabel('Your notes').fill('A small thought worth keeping.');
  await page.getByRole('radio',{name:'sage cover'}).check();
  await page.screenshot({path:'/tmp/chapter-checks/add-book.png',fullPage:true});
  await page.getByRole('button',{name:'Add to my library'}).click();
  await expect(page.getByRole('dialog')).toHaveCount(0);
  await expect(page.locator('.reading-card')).toHaveCount(4);
  await page.getByRole('link',{name:'A Book of Days — Browser Check',exact:true}).click();
  bookId=new URL(page.url()).pathname.split('/').at(-1);
  await expect(page.getByRole('heading',{name:'A Book of Days — Browser Check'})).toBeVisible();
  await expect(page.locator('.saved-notes')).toContainText('A small thought worth keeping.');
  await page.getByRole('button',{name:'Edit notes',exact:true}).click();
  await page.getByLabel('Your notes',{exact:true}).fill('A revised thought.\\n\\nAnother line, safely saved. <script>window.bad=true</script>');
  await page.getByRole('button',{name:'Save notes'}).click();
  await expect(page.locator('.saved-notes')).toContainText('Another line, safely saved.');
  await page.getByRole('button',{name:'Mark as finished',exact:true}).click();
  await expect(page.locator('.status-badge')).toHaveText('Finished');
  await page.getByRole('button',{name:'Share book'}).click();
  await expect(page.getByRole('button',{name:'Link copied'})).toBeVisible();
  const share=await page.evaluate(()=>navigator.clipboard.readText());
  expect(share).toBe(page.url());
  const sharedPage=await context.newPage();
  await sharedPage.goto(share,{waitUntil:'networkidle'});
  await expect(sharedPage.locator('.status-badge')).toHaveText('Finished');
  await expect(sharedPage.locator('.saved-notes')).toContainText('A revised thought.');
  expect(await sharedPage.evaluate(()=>window.bad)).toBeUndefined();
  await sharedPage.screenshot({path:'/tmp/chapter-checks/detail.png',fullPage:true});
  await sharedPage.setViewportSize({width:390,height:844});
  await sharedPage.screenshot({path:'/tmp/chapter-checks/detail-mobile.png',fullPage:true});
  expect(await sharedPage.evaluate(()=>document.documentElement.scrollWidth)).toBe(390);
  await sharedPage.close();
  await page.getByRole('link',{name:'Back to your library'}).click();
  await page.getByRole('button',{name:/"'^Finished 5/}).click();
  await expect(page.locator('"'.reading-card')).toHaveCount(0);
  await expect(page.locator('.finished-card')).toHaveCount(5);
  await page.getByRole('textbox',{name:'Search books'}).fill('Patti');
  await expect(page.locator('.finished-card')).toHaveCount(1);
  await page.getByRole('textbox',{name:'Search books'}).fill('nothing-matches-123');
  await expect(page.getByRole('heading',{name:'No books on this shelf match.'})).toBeVisible();
  await page.getByRole('button',{name:'Clear search',exact:true}).first().click();
  await page.getByRole('link',{name:'Reading notes',exact:true}).click();
  await expect(page.locator('.note-card')).toHaveCount(5);
  await page.getByRole('button',{name:/"'^All books/}).click();
  await expect(page.locator('"'.note-card')).toHaveCount(8);
  await page.goto("'`http://localhost:3000/books/${bookId}`);
  await page.getByRole('"'button',{name:'Edit book',exact:true}).click();
  await page.getByLabel('Book title').fill('A Book of Days — Edited');
  await page.getByRole('button',{name:'Save changes'}).click();
  await expect(page.getByRole('heading',{name:'A Book of Days — Edited'})).toBeVisible();
  await page.getByRole('button',{name:'Remove from library'}).click();
  await page.getByRole('button',{name:'Remove book',exact:true}).click();
  await expect(page).toHaveURL('http://localhost:3000/');
  await page.goto('http://localhost:3000/books/does-not-exist');
  await expect(page.getByRole('heading',{name:'This page is missing.'})).toBeVisible();
  expect(errors).toEqual([]);
  console.log('PASS: add, notes, finish, shared direct link, literal text rendering, filters, search, notes list, edit, remove, missing book, mobile detail, no browser errors.');
} finally {
  if(bookId) await fetch("'`http://localhost:3000/api/books/${bookId}`,{method:'"'DELETE'});
  await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
  await page.screenshot({path:'/tmp/chapter-checks/desktop-final.png',fullPage:true});
  await page.setViewportSize({width:390,height:844});
  await page.screenshot({path:'/tmp/chapter-checks/mobile-final.png',fullPage:true});
  await browser.close();
}
JS"

