import { mkdtemp, rm, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { chromium, expect } from '/workspace/node_modules/@playwright/test/index.mjs';
const directory = await mkdtemp(path.join(tmpdir(),'chapter-production-'));
let server, browser;
async function start() {
  server=spawn(process.execPath,['server.js'],{cwd:'/workspace',env:{...process.env,NODE_ENV:'production',PORT:'3001',BOOKS_FILE:path.join(directory,'books.json'),EMPTY_LIBRARY:'1'},stdio:['ignore','pipe','pipe']});
  await new Promise((resolve,reject)=>{server.stdout.on('data',chunk=>{if(chunk.toString().includes('Chapter is ready')) resolve();});server.once('error',reject);server.once('exit',code=>reject(new Error("'`Server exited ${code}`)));});
}
async function stop() { await new Promise(resolve=>{server.once('"'exit',resolve);server.kill('SIGTERM');}); }
try {
  await start();
  assert.deepEqual(await (await fetch('http://localhost:3001/api/books')).json(),[]);
  const book=await (await fetch('http://localhost:3001/api/books',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:'A Book of Days and Other Small Discoveries',author:'Patti Smith',notes:'Words worth keeping.',color:'sage'})})).json();
  await fetch("'`http://localhost:3001/api/books/${book.id}`,{method:'"'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({notes:'Saved before the restart.',status:'finished'})});
  await stop();
  await start();
  const persisted=await(await fetch("'`http://localhost:3001/api/books/${book.id}`)).json();
  assert.equal(persisted.notes,'"'Saved before the restart.');
  assert.equal(persisted.status,'finished');
  assert.equal(JSON.parse(await readFile(path.join(directory,'books.json'),'utf8'))[0].id,book.id);
  const direct=await fetch("'`http://localhost:3001/books/${book.id}`);
  assert.equal(direct.status,200);
  assert.ok((await direct.text()).includes('"'id=\"root\"'));
  browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-gpu']});
  const page=await browser.newPage({viewport:{width:1440,height:1000}});
  await page.goto("'`http://localhost:3001/books/${book.id}`,{waitUntil:'"'networkidle'});
